/* ---------- AdminHome.html ---------- */
/*
 * Admin home (الرئيسية): one look at what matters this week.
 *  - the site: unpublished changes, errors, last publish, GitHub
 *  - the next meeting and its topic (or a button to add one)
 *  - what's coming up: scheduled news, games, competitions, activities
 *  - what the bell shows right now
 *  - quick actions (+ موضوع، + خبر، + مسابقة، + فعالية…)
 * The timeline (الجدول) follows below. Everything in Cairo time.
 */
(function () {

  'use strict';

  var A = window.A;
  var el = A.el;
  var icon = A.icon;
  var bool = A.bool;

  var DAY = 1440;

  function now() { return A.wallMinutes(A.cairoNow()); }

  function upgraded() { return A.state.schema && A.state.schema.data >= A.state.schema.target; }

  /* "النهارده" / "بكره" / "بعد ٣ أيام" */
  function relative(minutes) {

    var today = Math.floor(now() / DAY);
    var day = Math.floor(minutes / DAY);
    var diff = day - today;
    var text = diff === 0 ? 'النهارده' : diff === 1 ? 'بكره' : diff === 2 ? 'بعد بكره' : diff < 0 ? 'من ' + (-diff) + ' يوم' : 'بعد ' + diff + ' أيام';
    if (diff > 10) text = 'بعد ' + diff + ' يوم';
    return text.replace(/\d/g, function (x) { return '٠١٢٣٤٥٦٧٨٩'[x]; });

  }

  function dashCard(options) {

    return el('section', { class: 'card dash-card' + (options.className ? ' ' + options.className : ''), 'aria-labelledby': options.id },
      el('div', { class: 'dash-card__head' },
        el('span', { class: 'dash-card__icon', 'aria-hidden': 'true' }, icon(options.icon)),
        el('h2', { class: 'card__title', id: options.id, text: options.title }),
        options.chip || null
      ),
      options.body
    );

  }


  /* =======================================================
     THE SITE: publish status
  ======================================================= */

  function siteCard() {

    var s = A.state.status;
    var config = A.state.config || {};
    var github = config.repo && config.tokenSet;
    var state = s.errors.length ? 'error' : s.hasChanges ? 'dirty' : 'clean';

    var words = {
      error: { title: 'يوجد خطأ يمنع النشر', text: 'صلّح ' + (s.errors.length === 1 ? 'الخطأ' : 'الأخطاء') + ' الأول، وبعدين انشر.', kind: 'danger', icon: 'alert' },
      dirty: { title: 'في تغييرات مستنية النشر', text: 'الزوار لسه شايفين النسخة القديمة لحد ما تنشر.', kind: 'gold', icon: 'send' },
      clean: { title: 'الموقع متحدث', text: 'كل اللي في المسودة ظاهر على الموقع.', kind: 'ok', icon: 'check' }
    }[state];

    var actions = el('div', { class: 'actions' },
      state !== 'clean'
        ? el('button', { class: 'btn btn--primary', type: 'button', onclick: function () { A.openReview(); } }, icon(state === 'error' ? 'alert' : 'send'), state === 'error' ? 'شوف الأخطاء' : 'راجع وانشر')
        : null,
      state !== 'clean' && config.siteUrl
        ? el('button', { class: 'btn', type: 'button', onclick: function () { A.openPreview(); } }, icon('eye'), 'معاينة')
        : null,
      config.siteUrl ? el('a', { class: 'btn btn--ghost', href: config.siteUrl, target: '_blank', rel: 'noopener' }, icon('external'), 'افتح الموقع') : null
    );

    var facts = el('dl', { class: 'dash-facts' },
      el('div', {}, el('dt', { text: 'آخر نشر' }), el('dd', { text: s.publishedAt ? A.formatIso(s.publishedAt) : 'لسه متنشرش' })),
      el('div', {}, el('dt', { text: 'GitHub' }), el('dd', {},
        A.chip(github ? 'متوصل' : 'مش متظبط', github ? 'ok' : 'danger'),
        s.publishedCommit && config.repo
          ? el('a', { class: 'dash-facts__link', href: 'https://github.com/' + config.repo + '/commit/' + s.publishedCommit, target: '_blank', rel: 'noopener', text: s.publishedCommit.slice(0, 7) })
          : null
      )),
      s.warnings && s.warnings.length ? el('div', {}, el('dt', { text: 'تنبيهات' }), el('dd', { text: String(s.warnings.length).replace(/\d/g, function (x) { return '٠١٢٣٤٥٦٧٨٩'[x]; }) + ' (مش بتمنع النشر)' })) : null
    );

    return el('section', { class: 'card dash-site dash-site--' + state, 'aria-labelledby': 'dash-site-title' },
      el('div', { class: 'dash-site__main' },
        el('span', { class: 'dash-site__icon', 'aria-hidden': 'true' }, icon(words.icon)),
        el('div', {},
          el('h2', { class: 'card__title', id: 'dash-site-title', text: words.title }),
          el('p', { class: 'card__hint', text: words.text })
        )
      ),
      facts,
      actions
    );

  }


  /* =======================================================
     THE NEXT MEETING
  ======================================================= */

  /* the next meeting that hasn't ended, and any cancelled ones before it */
  A.nextMeeting = function () {

    var draft = A.state.draft;
    var days = A.state.meta.days || [];
    var weekday = days.indexOf(String(A.setting('meeting.day')));
    var time = A.setting('meeting.time') || '20:00';
    var duration = +A.setting('meeting.durationMinutes') || 120;
    var current = now();
    var today = Math.floor(current / DAY);
    var byDate = {};
    var dates = {};

    (draft.sessions || []).filter(function (s) { return bool(s.enabled); }).forEach(function (s) {
      byDate[s.date] = s;
      dates[s.date] = true;
    });

    if (weekday !== -1) {
      for (var i = 0; i < 70; i++) {
        var day = today + i;
        if (new Date(day * DAY * 60000).getUTCDay() === weekday) {
          dates[A.wallFromMinutes(day * DAY).slice(0, 10)] = true;
        }
      }
    }

    var cancelled = [];
    var sorted = Object.keys(dates).sort();

    for (var j = 0; j < sorted.length; j++) {
      var date = sorted[j];
      var session = byDate[date] || null;
      var at = A.wallMinutes(date + ' ' + ((session && session.time) || time));
      var end = at + ((session && +session.durationMinutes) || duration);
      if (at === null || end < current) continue;
      if (session && session.status === 'cancelled') {
        cancelled.push(date);
        continue;
      }
      return { date: date, at: at, live: at <= current, session: session, cancelled: cancelled };
    }

    return { date: '', cancelled: cancelled };

  };

  function meetingCard() {

    var row = (A.state.layout || []).filter(function (s) { return s.key === 'meeting'; })[0] || { enabled: true };
    var shown = A.visibility(bool(row.enabled), row.visibleFrom, row.visibleUntil);
    var off = shown.state === 'off' || shown.state === 'ended';
    var next = A.nextMeeting();
    var body = [];

    if (off) {
      body.push(el('p', { class: 'note note--warn', text: 'ركن الاجتماع مخفي من الموقع: الزوار مش شايفين ميعاد ولا موضوع.' }));
    }

    next.cancelled.forEach(function (date) {
      body.push(el('p', { class: 'dash-meeting__cancelled' }, icon('alert'), 'مفيش اجتماع ' + A.formatWall(date, false) + ' (ملغي)'));
    });

    if (!next.date) {
      body.push(el('p', { class: 'empty', text: 'مفيش ميعاد اجتماع متظبط.' }));
      body.push(el('div', { class: 'actions' }, el('button', { class: 'btn btn--primary', type: 'button', onclick: function () { A.go('content', 'meetings'); } }, 'ظبط الميعاد')));
      return dashCard({ id: 'dash-meeting-title', icon: 'church', title: 'الاجتماع الجاي', body: body });
    }

    var session = next.session;
    var topic = session && session.topic;

    body.push(el('div', { class: 'dash-meeting' },
      el('p', { class: 'dash-meeting__when' },
        el('strong', { text: A.formatWall(A.wallFromMinutes(next.at)) }),
        el('span', { class: 'dash-meeting__rel', text: next.live ? 'شغال دلوقتي' : relative(next.at) })
      ),
      el('p', { class: 'dash-meeting__topic' + (topic ? '' : ' is-empty') }, topic ? '«' + topic + '»' : 'لسه مفيش موضوع للاجتماع ده'),
      session && session.speaker ? el('p', { class: 'card__hint', text: session.speaker }) : null,
      topic && session.visibleFrom && A.wallMinutes(session.visibleFrom) > now()
        ? A.chip('الموضوع يظهر ' + A.formatWall(session.visibleFrom), 'gold')
        : null
    ));

    // the meeting is on now and has a program: which stage is happening (live.json)
    if (next.live && session && A.liveControl && A.programStages(session.program).length) {
      body.push(A.liveControl(session));
    }

    body.push(el('div', { class: 'actions' },
      el('button', { class: 'btn ' + (topic ? 'btn--ghost' : 'btn--primary'), type: 'button', onclick: function () {
        A.editors.sessions(session, session ? null : { date: next.date });
      } }, icon(topic ? 'edit' : 'plus'), topic ? 'تعديل الموضوع' : 'أضف موضوع'),
      el('button', { class: 'btn btn--ghost', type: 'button', onclick: function () { A.go('content', 'meetings'); } }, 'كل الاجتماعات')
    ));

    return dashCard({
      id: 'dash-meeting-title',
      icon: 'church',
      title: 'الاجتماع الجاي',
      chip: off ? A.chip('مخفي', 'off') : null,
      className: off ? 'is-off' : '',
      body: body
    });

  }


  /* =======================================================
     COMING UP (two weeks) + LIVE NOW
  ======================================================= */

  function sectionOfType(key) {

    var type = (A.state.draft.types || []).filter(function (t) { return t.key === key; })[0];
    return type && type.section === 'competitions' ? 'competitions' : 'activities';

  }

  function upcoming() {

    var draft = A.state.draft;
    var current = now();
    var until = current + 14 * DAY;
    var rows = [];

    function add(at, kind, item, label, iconName, live) {
      var minutes = A.wallMinutes(at);
      if (minutes === null) return;
      if (!live && (minutes < current || minutes > until)) return;
      rows.push({ minutes: live ? current : minutes, at: at, kind: kind, item: item, label: label, icon: iconName, live: !!live });
    }

    var visible = function (item) { return bool(item.enabled) && !bool(item.archived); };

    (draft.news || []).filter(visible).forEach(function (n) {
      add(n.publishAt, 'news', n, 'خبر هيتنشر: ' + n.title, 'megaphone');
    });

    (draft.games || []).filter(visible).forEach(function (g) {
      var start = A.wallMinutes(g.startAt);
      var end = A.wallMinutes(g.endAt);
      if (start !== null && end !== null && start <= current && current < end) add(g.startAt, 'games', g, 'لعبة شغالة: ' + g.title, 'star', true);
      else add(g.startAt, 'games', g, 'لعبة تبدأ: ' + g.title, 'star');
    });

    (draft.activities || []).filter(visible).forEach(function (a) {
      var competition = sectionOfType(a.type) === 'competitions';
      var start = A.wallMinutes(a.startAt);
      var end = A.wallMinutes(a.endAt, true);
      var noun = competition ? 'مسابقة' : 'فعالية';
      if (start !== null && start <= current && (end === null || current <= end)) add(a.startAt, 'activities', a, noun + ' شغالة: ' + a.title, competition ? 'trophy' : 'calendar', true);
      else add(a.startAt, 'activities', a, noun + ' تبدأ: ' + a.title, competition ? 'trophy' : 'calendar');
    });

    return rows.sort(function (a, b) { return (b.live - a.live) || (a.minutes - b.minutes); });

  }

  function upcomingCard() {

    var rows = upcoming();
    var shown = rows.slice(0, 7);

    return dashCard({
      id: 'dash-upcoming-title',
      icon: 'calendar',
      className: 'dash-card--wide',
      title: 'جاي قريب',
      body: [
        el('p', { class: 'card__hint', text: 'الأخبار والألعاب والمسابقات والفعاليات في الأسبوعين الجايين.' }),
        shown.length
          ? el('ul', { class: 'dash-list' }, shown.map(function (row) {
            return el('li', {},
              el('button', { class: 'dash-row' + (row.live ? ' is-live' : ''), type: 'button', onclick: function () { A.editors[row.kind](row.item); } },
                el('span', { class: 'dash-row__icon', 'aria-hidden': 'true' }, icon(row.icon)),
                el('span', { class: 'dash-row__label', text: row.label }),
                el('span', { class: 'dash-row__when', text: row.live ? 'دلوقتي' : relative(row.minutes) + '، ' + (A.formatWall(row.at).split('، ')[1] || '') })
              )
            );
          }))
          : el('p', { class: 'empty', text: 'مفيش حاجة متجدولة في الأسبوعين الجايين.' }),
        rows.length > shown.length ? el('p', { class: 'card__hint', text: '+ ' + (rows.length - shown.length) + ' كمان في الجدول تحت' }) : null
      ]
    });

  }

  function bellCard() {

    var days = A.state.meta.historyDays;
    var current = now();
    var live = (A.state.draft.notifications || []).filter(function (n) {
      if (!bool(n.enabled) || bool(n.archived)) return false;
      var until = n.expireAt || (n.publishAt ? A.wallFromMinutes(A.wallMinutes(n.publishAt) + days * DAY) : '');
      var v = A.visibility(true, n.publishAt, until, current);
      return v.state === 'live' || v.state === 'always';
    }).sort(function (a, b) { return (b.publishAt || '') < (a.publishAt || '') ? -1 : 1; });

    var count = String(live.length).replace(/\d/g, function (x) { return '٠١٢٣٤٥٦٧٨٩'[x]; });

    return dashCard({
      id: 'dash-bell-title',
      icon: 'bell',
      title: 'الجرس دلوقتي',
      chip: A.chip(count + (live.length === 1 ? ' إشعار' : ' إشعارات'), live.length ? 'ok' : 'off'),
      body: [
        live.length
          ? el('ul', { class: 'dash-list' }, live.slice(0, 4).map(function (n) {
            return el('li', {},
              el('button', { class: 'dash-row', type: 'button', onclick: function () { A.editors.notifications(n); } },
                el('span', { class: 'dash-row__icon', 'aria-hidden': 'true' }, icon('bell')),
                el('span', { class: 'dash-row__label', text: n.title }),
                el('span', { class: 'dash-row__when', text: n.publishAt ? relative(A.wallMinutes(n.publishAt)) : '' })
              )
            );
          }))
          : el('p', { class: 'empty', text: 'الجرس فاضي دلوقتي.' }),
        el('div', { class: 'actions' },
          el('button', { class: 'btn btn--ghost', type: 'button', onclick: function () { A.go('content', 'notifications'); } }, 'كل الإشعارات')
        )
      ]
    });

  }


  /* =======================================================
     QUICK ACTIONS
  ======================================================= */

  function quickCard() {

    function quick(label, iconName, onclick) {
      return el('button', { class: 'quick', type: 'button', onclick: onclick },
        el('span', { class: 'quick__icon', 'aria-hidden': 'true' }, icon(iconName)),
        el('span', { class: 'quick__label', text: label })
      );
    }

    var items = upgraded();

    return el('section', { class: 'card dash-quick', 'aria-labelledby': 'dash-quick-title' },
      el('h2', { class: 'card__title', id: 'dash-quick-title', text: 'اعمل حاجة جديدة' }),
      el('div', { class: 'quick-grid' },
        quick('موضوع اجتماع', 'church', function () {
          var next = A.nextMeeting();
          A.editors.sessions(next.session, next.session ? null : (next.date ? { date: next.date } : null));
        }),
        quick('خبر', 'megaphone', function () { A.editors.news(null); }),
        items ? quick('مسابقة', 'trophy', function () { A.editors.activities(null, 'competitions'); }) : null,
        items ? quick('فعالية', 'calendar', function () { A.editors.activities(null, 'activities'); }) : null,
        quick('لعبة', 'star', function () { A.editors.games(null); }),
        quick('إشعار', 'bell', function () { A.editors.notifications(null); }),
        quick('صورة', 'photos', function () { A.go('media'); })
      ),
      el('p', { class: 'card__hint', text: 'كل حاجة بتتحفظ مسودة، وتظهر في معادها بتوقيت مصر بعد ما تنشر.' })
    );

  }


  /* the home view: the dashboard, then the timeline (AdminContent) */
  A.dashboard = function () {

    return el('div', { class: 'dash' },
      siteCard(),
      meetingCard(),
      bellCard(),
      quickCard(),
      upcomingCard()
    );

  };

})();

/* ---------- AdminPreview.html ---------- */
/*
 * PREVIEW (معاينة): the draft on the real page, before publishing.
 *
 * The page is built here, as this admin page's own frame (srcdoc): the
 * site's index.html with <html data-preview> and a <base> pointing at the
 * site, so it runs the site's own CSS and JS. The draft is handed to it by
 * postMessage, same origin only. So:
 *  - drafts never reach GitHub or the public site's cache. In Apps Script
 *    the frame has the admin's own origin; on the official admin page
 *    (GitHub Pages /admin/) it shares the site's origin, so a guard script
 *    (admin/preview-guard.js) swaps the page's storage for memory first;
 *  - the public site keeps refusing to be framed by anyone (unchanged);
 *  - images not on the site yet are shown from Drive previews (blob: URLs).
 * Phone / computer widths, and time travel (Cairo time).
 */
(function () {

  'use strict';

  var A = window.A;
  var el = A.el;
  var icon = A.icon;

  var DEVICES = {
    phone: { width: 390, height: 844, label: 'موبايل' },
    desktop: { width: 1280, height: 860, label: 'كمبيوتر' }
  };

  var view = null;      // the open preview: { frame, stage, status, ... }
  var blobs = {};       // media id -> blob: URL (kept for the session)
  var pageHtml = {};    // site URL -> the prepared page

  function siteBase() {

    var url = (A.state.config && A.state.config.siteUrl) || '';
    return url ? url.replace(/\/?$/, '/') : '';

  }

  /* the site's own page, made to run here: same files, preview mode */
  function previewPage(base) {

    if (pageHtml[base]) return Promise.resolve(pageHtml[base]);

    var origin = new URL(base).origin;

    return fetch(base + 'index.html?preview=' + Date.now(), { cache: 'no-store' })
      .then(function (response) {
        if (!response.ok) throw new Error('index.html: HTTP ' + response.status);
        return response.text();
      })
      .then(function (html) {
        html = html.replace(/<html\b([^>]*)>/i, '<html$1 data-preview>');
        // On the official admin page (GitHub Pages /admin/) this frame shares
        // the site's own origin, so its storage is the visitors' storage on
        // this browser. The guard runs first and gives the page a storage of
        // its own (memory only): the draft never lands in the site's cache,
        // bell or anything else saved for the real site.
        var guard = origin === location.origin ? '<script src="' + base + 'admin/preview-guard.js"><' + '/script>' : '';
        html = html.replace(/<head>/i, '<head><base href="' + base + '">' + guard);
        // the same rules, naming the site's origin ('self' is this admin page now)
        html = html.replace(/(<meta http-equiv="Content-Security-Policy" content=")([^"]*)(")/i, function (_, open, csp, close) {
          csp = csp.replace(/'self'/g, "'self' " + origin)
            .replace(/base-uri 'none'/, 'base-uri ' + origin)
            .replace(/;?\s*upgrade-insecure-requests/, '');
          return open + csp + close;
        });
        pageHtml[base] = html;
        return html;
      });

  }

  /* a data: URL decoded here (a strict CSP's connect-src doesn't allow
     fetching data: URLs); anything else is fetched */
  function toBlob(url) {

    var match = /^data:([\w.+\/-]+)?(;base64)?,(.*)$/.exec(url || '');

    if (!match) {
      return fetch(url).then(function (response) { return response.blob(); });
    }

    var text = match[2] ? atob(match[3]) : decodeURIComponent(match[3]);
    var bytes = new Uint8Array(text.length);
    for (var i = 0; i < text.length; i++) bytes[i] = text.charCodeAt(i) & 255;

    return Promise.resolve(new Blob([bytes], { type: match[1] || 'application/octet-stream' }));

  }

  /* images not published yet: our Drive previews, as blob: URLs (no commas,
     so they work in srcset too). The page swaps them in after its sanitizer
     (which only accepts the site's own media paths). Returns path -> URL. */
  function pendingImages(pending) {

    var map = {};

    return Promise.all(pending.map(function (media) {
      var ready = blobs[media.id]
        ? Promise.resolve(blobs[media.id])
        : A.mediaPreview(media.id)
          .then(toBlob)
          .then(function (blob) { blobs[media.id] = URL.createObjectURL(blob); return blobs[media.id]; });
      return ready.then(function (url) {
        // a video: only its poster has a preview here (the clip plays once published)
        if (media.kind !== 'video') map[media.path] = url;
        map[media.thumb] = url;
      }).catch(function () {});
    })).then(function () { return map; });

  }

  /* still on screen? (the sheet may have closed or moved on to the review) */
  function open() {

    return !!(view && view.frame.isConnected);

  }

  function setStatus(text, kind) {

    if (!view) return;
    view.status.className = 'preview-status' + (kind ? ' preview-status--' + kind : '');
    A.fill(view.status, kind === 'busy' ? el('span', { class: 'spinner spinner--inline', 'aria-hidden': 'true' }) : null, text);

  }

  /* fit the chosen device width into the space we have */
  function fit() {

    if (!view) return;
    var device = DEVICES[view.device];
    var room = view.stage.clientWidth;
    var scale = Math.min(1, room / device.width);
    var height = Math.max(420, Math.min(device.height, (window.innerHeight - 260) / scale));
    view.frame.style.width = device.width + 'px';
    view.frame.style.height = height + 'px';
    view.frame.style.transform = 'scale(' + scale + ')';
    view.holder.style.width = Math.round(device.width * scale) + 'px';
    view.holder.style.height = Math.round(height * scale) + 'px';
    view.stage.dataset.device = view.device;

  }

  /* fetch the draft as of the chosen moment and hand it to the page */
  function load() {

    if (!view) return;
    var token = view.token = (view.token || 0) + 1;
    setStatus('بنجهز المعاينة…', 'busy');

    A.call('apiPreview', view.at || '')
      .then(function (result) {
        return pendingImages(result.pending || []).then(function (images) {
          return { result: result, content: result.content, images: images };
        });
      })
      .then(function (data) {
        if (!view || token !== view.token) return;
        // "now" keeps the visitor's real clock; a chosen moment moves it there
        view.pendingMessage = { type: 'athanasios:preview', content: data.content, images: data.images, at: view.at ? data.result.at : null };
        view.lastResult = data.result;
        send();
      })
      .catch(function (error) {
        if (!view || token !== view.token) return;
        setStatus(A.parseError(error).message, 'error');
      });

  }

  function send() {

    if (!open() || !view.ready || !view.pendingMessage) return;
    view.frame.contentWindow.postMessage(view.pendingMessage, location.origin);
    view.pendingMessage = null;

  }

  /* only our own frame, on our own origin */
  window.addEventListener('message', function (event) {

    if (!open() || event.source !== view.frame.contentWindow || event.origin !== location.origin) return;
    var data = event.data || {};

    if (data.type === 'athanasios:preview-ready') {
      view.ready = true;
      send();
    }
    else if (data.type === 'athanasios:preview-shown') {
      var r = view.lastResult || {};
      var when = view.at ? 'زي ما هيبان ' + A.formatWall(r.at.replace('T', ' ')) : 'زي ما هيبان دلوقتي بعد النشر';
      var issues = (r.errors || []).length ? ' — في ' + r.errors.length + ' خطأ لازم يتصلح قبل النشر' : '';
      setStatus(when + issues, issues ? 'warn' : 'ok');
    }
    else if (data.type === 'athanasios:preview-error') {
      setStatus('المعاينة مقدرتش تعرض المسودة: ' + data.message, 'error');
    }

  });

  window.addEventListener('resize', function () { fit(); });


  /* =======================================================
     THE SHEET
  ======================================================= */

  function segmented(label, options, selected, onchange) {

    var buttons = options.map(function (option) {
      return el('button', {
        class: 'segment',
        type: 'button',
        'aria-pressed': String(option.value === selected),
        onclick: function (event) {
          buttons.forEach(function (b) { b.setAttribute('aria-pressed', String(b === event.currentTarget)); });
          onchange(option.value);
        }
      }, option.icon ? icon(option.icon) : null, option.label);
    });

    return el('div', { class: 'segmented', role: 'group', 'aria-label': label }, buttons);

  }

  function timeOptions() {

    var options = [{ value: '', label: 'دلوقتي' }];
    var next = A.nextMeeting ? A.nextMeeting() : null;

    if (next && next.date && next.at) {
      options.push({ value: A.wallFromMinutes(next.at - 120), label: 'قبل الاجتماع بساعتين' });
      options.push({ value: A.wallFromMinutes(next.at + 20), label: 'أثناء الاجتماع' });
    }

    var tomorrow = (Math.floor(A.wallMinutes(A.cairoNow()) / 1440) + 1) * 1440 + 10 * 60;
    options.push({ value: A.wallFromMinutes(tomorrow), label: 'بكره ١٠ الصبح' });

    return options;

  }

  A.openPreview = function () {

    var base = siteBase();

    if (!base) {
      A.toast('عنوان الموقع (SITE_URL) مش متظبط — المعاينة محتاجاه', true);
      return;
    }

    var frame = el('iframe', { class: 'preview-frame', title: 'معاينة الموقع', loading: 'eager', referrerpolicy: 'no-referrer' });
    var holder = el('div', { class: 'preview-holder' }, frame);
    var stage = el('div', { class: 'preview-stage' }, holder);
    var status = el('p', { class: 'preview-status', role: 'status' });

    var custom = el('input', { class: 'input preview-when', type: 'datetime-local', 'aria-label': 'تاريخ ووقت المعاينة (بتوقيت مصر)' });

    view = { frame: frame, holder: holder, stage: stage, status: status, device: matchMedia('(min-width: 900px)').matches ? 'desktop' : 'phone', at: '', ready: false };

    var devices = segmented('حجم الشاشة', [
      { value: 'phone', label: DEVICES.phone.label, icon: 'phone' },
      { value: 'desktop', label: DEVICES.desktop.label, icon: 'globe' }
    ], view.device, function (value) { view.device = value; fit(); });

    var times = segmented('وقت المعاينة', timeOptions(), '', function (value) {
      view.at = value;
      custom.value = '';
      load();
    });

    custom.addEventListener('change', function () {
      if (!custom.value) return;
      view.at = custom.value.replace('T', ' ');
      times.querySelectorAll('.segment').forEach(function (b) { b.setAttribute('aria-pressed', 'false'); });
      load();
    });

    A.openSheet('معاينة قبل النشر', [
      el('p', { class: 'note', text: 'دي المسودة على صفحة الموقع نفسها. محدش شايفها غيرك — الزوار مش هيشوفوا التغييرات غير بعد النشر.' }),
      el('div', { class: 'preview-tools' },
        devices,
        el('div', { class: 'preview-tools__time' }, times, custom)
      ),
      status,
      stage
    ], [
      el('button', { class: 'btn btn--primary', type: 'button', onclick: function () { A.openReview(); } }, icon('send'), 'راجع وانشر'),
      el('button', { class: 'btn btn--ghost', type: 'button', text: 'قفل', onclick: function () { A.closeSheet(); } })
    ], { wide: true, className: 'sheet--preview' });

    // the page is what to look at, not the date field
    var heading = document.getElementById('sheet-title');
    if (heading) heading.focus({ preventScroll: true });

    fit();
    setStatus('بنجهز المعاينة…', 'busy');

    var current = view;
    previewPage(base)
      .then(function (html) {
        if (view !== current) return;
        frame.srcdoc = html;
        load();
      })
      .catch(function (error) {
        if (view !== current) return;
        setStatus('مقدرناش نفتح صفحة الموقع للمعاينة (' + error.message + ').', 'error');
      });

  };

})();
